export type DiscoverResourcesParams = {
/**
 * Search query. Blank queries are rejected with 400
 * @minLength 1
 */
q: string;
/**
 * Formats wanted, comma-separated from article, video, pdf, podcast, interactive and other. One value behaves as it always did; several widen, because a reader who wants a video or a pdf should not have to search twice
 */
format?: string;
subject?: string;
gradeLevel?: string;
/**
 * Required result language, or any to allow all languages
 */
language?: DiscoverResourcesLanguage;
/**
 * Page number. Each page resumes where the previous one ended, so a page past the stored results returns an empty list rather than repeating earlier ones
 * @minimum 1
 */
page?: number;
/**
 * Return specific learning content, direct publisher websites and channels, or public social, scholarly, or university profiles for people discovery
 */
resultType?: DiscoverResourcesResultType;
/**
 * Search the live public web in addition to the stored catalog. Signed-in requests use their AI discovery allowance; anonymous requests continue to receive stored-catalog results without spending AI capacity.
 */
includeWeb?: boolean;
/**
 * Title or description must contain this phrase, truncated to 160 characters
 */
exactPhrase?: string;
/**
 * Space-separated words to exclude, truncated to 160 characters; the first eight are applied
 */
exclude?: string;
/**
 * Restrict to providers whose name contains this text, truncated to 160 characters
 */
source?: string;
/**
 * Drop results whose provider, link or provider site contains this text, truncated to 160 characters. Matched against all three so "Wikipedia" and "wikipedia.org" exclude the same results
 */
excludeSource?: string;
/**
 * Kinds of material wanted, comma-separated: book, course, reference, paper, primary, video. The catalog holds all six and a revision search and a research search want opposite ends of that list. Results stored before their source declared a material are absent from a filtered result rather than guessed into one
 */
material?: string;
/**
 * Comma-separated subjects to drop, up to twelve. Distinct from `exclude`, which matches anywhere: this one is about how a work is filed
 */
excludeSubjects?: string;
/**
 * Author or contributor name to match, truncated to 160 characters
 */
author?: string;
/**
 * Require the query to match a work's own title or subject rather than its description, so the topic is what the work is about instead of something it mentions. Sent as the string true or false
 */
titleOnly?: boolean;
/**
 * Require, or require the absence of, a preview image. Sent as the string true or false
 */
hasThumbnail?: boolean;
/**
 * Earliest publication year, inclusive. Works with no recorded publication date are excluded rather than assumed recent
 * @minimum 1000
 * @maximum 2200
 */
publishedFrom?: number;
/**
 * Latest publication year, inclusive
 * @minimum 1000
 * @maximum 2200
 */
publishedTo?: number;
/**
 * Resume after this point in the ranking, as the largest `cursor` the client already holds. Preferred over `page` for reading further into the stored catalog: the catalog grows while a reader pages, and a positional offset then hands back results an earlier page already showed. Ignored when it does not parse
 * @maxLength 40
 */
after?: string;
/**
 * The largest `catalogId` the client already holds. Sent with `after`: works stored while the client was reading can rank above the point it has read to, and would otherwise never be offered. Rows newer than this are returned whatever their rank
 * @minimum 0
 */
sinceId?: number;
/**
 * How recent a result must be. The stored catalog filters on year and three_years; the shorter windows only steer AI discovery
 */
freshness?: DiscoverResourcesFreshness;
/**
 * Required source credibility
 */
sourceQuality?: DiscoverResourcesSourceQuality;
/**
 * Difficulty hint; applies to AI discovery only, content results only
 */
difficulty?: DiscoverResourcesDifficulty;
/**
 * Access requirement, content results only. The stored catalog filters on free and open; no_account only steers AI discovery
 */
accessType?: DiscoverResourcesAccessType;
/**
 * Require a stated licence, or one that permits reuse. Content results only
 */
license?: DiscoverResourcesLicense;
/**
 * Length hint; applies to AI discovery only, content results only
 */
contentLength?: DiscoverResourcesContentLength;
/**
 * Require captions, sent as the string true or false. Applies to AI discovery only, content results only
 */
captions?: boolean;
/**
 * Require a transcript, sent as the string true or false. Applies to AI discovery only, content results only
 */
transcript?: boolean;
};

